function addBolt(origin,target){const dir=target.clone().sub(origin);dir.y=0;dir.normalize();const mesh=new THREE.Mesh(new THREE.SphereGeometry(.14,10,8),new THREE.MeshBasicMaterial({color:0xd9ff8c}));mesh.position.copy(origin);const glow=new THREE.PointLight(0xc8f169,5,3);mesh.add(glow);scene.add(mesh);bolts.push({mesh,dir,life:1.35});}
function shoot(){const now=performance.now()/1000;if(now-shotAt<.28||energy<5)return;shotAt=now;energy-=5;const origin=player.position.clone().add(new THREE.Vector3(0,1.7,0));addBolt(origin,aimPoint);updateHUD()}
function impact(point){const ringFx=new THREE.Mesh(new THREE.TorusGeometry(.25,.045,5,16),new THREE.MeshBasicMaterial({color:0xff9a70,transparent:true,opacity:.9}));ringFx.position.copy(point);ringFx.rotation.x=Math.PI/2;scene.add(ringFx);particles.push({mesh:ringFx,life:.35,kind:'impact'});}
function finish(won){if(gameEnded)return;gameEnded=true;running=false;document.getElementById('endkicker').textContent=won?'MISSION COMPLETE':'MISSION FAILED';document.getElementById('endtitle').textContent=won?'RELAY SECURE':'OUTPOST LOST';document.getElementById('endsub').textContent=won?'THE OUTPOST HOLDS. HOSTILES NEUTRALIZED: '+score:'THE RELAY HAS GONE DARK. HOSTILES NEUTRALIZED: '+score;document.getElementById('end').classList.remove('hidden')}
function setAimFromPointer(clientX,clientY){mouse.x=clientX/innerWidth*2-1;mouse.y=-(clientY/innerHeight)*2+1;raycaster.setFromCamera(mouse,camera);const hit=new THREE.Vector3();if(raycaster.ray.intersectPlane(groundPlane,hit))aimPoint.copy(hit);const cross=document.querySelector('.crosshair');cross.style.left=clientX+'px';cross.style.top=clientY+'px'}
window.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')setAimFromPointer(e.clientX,e.clientY)});
renderer.domElement.addEventListener('pointerdown',e=>{if(!running||e.pointerType!=='mouse')return;setAimFromPointer(e.clientX,e.clientY);mouseDown=true;shoot()});window.addEventListener('pointerup',()=>mouseDown=false);
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dashAt=performance.now()/1000});window.addEventListener('keyup',e=>keys[e.code]=false);
